#!/usr/bin/env python3
"""Generate the additive H24 interface; --check verifies exact output."""
from pathlib import Path
import sys
TARGET = Path('Solidity/Lowering/P8/DeclarationGraphAdmission.lean')
CONTENT = 'import Solidity.Lowering.V07.LocationGraphInterface\n\n/-! H24 additive declaration-graph admission companion.\nGenerated by scripts/generate-p8-declaration-graph-interface.py.\nFrozenInterface.Producer and H15 Admission are unchanged. This interface\nrequires BOTH all-admitted admissible-location certificates and actual Source\nrefusal, indexed by the exact acceptedSource, artifact and location. It is\nnot an inhabitant, a total graph producer or evidence of concrete admission.\n-/\nnamespace Solidity.Lowering.P8.DeclarationGraphAdmission\nopen P8a\n\n/-- The H24 producer field uses the owner-reviewed H15 contract verbatim.\nNo obsolete all-locations DeclarationGraph obligation is introduced. -/\nstructure Producer (S : Spec) (reference : OperationalReference)\n    (origins : SourceOrigins S) (roots : RootModel S) where\n  base : P8a.Producer S reference origins roots\n  declarationGraphs : V07.LocationGraphInterface.Admission base\n\nend Solidity.Lowering.P8.DeclarationGraphAdmission\n'
if sys.argv[1:] == ['--check']:
    raise SystemExit(0 if TARGET.read_text() == CONTENT else 1)
if sys.argv[1:]:
    raise SystemExit('usage: generate-p8-declaration-graph-interface.py [--check]')
TARGET.write_text(CONTENT)
